1	export const PENDING_PROMPT_KEY = "kodely:pending_prompt";
2	// A reference image attached on the homepage before signing up, carried
3	// through the auth wall the same way the prompt text is. Stored as a data
4	// URL (already downscaled client-side — see PromptHero) so it comfortably
5	// fits sessionStorage's per-origin limit.
6	export const PENDING_PROMPT_IMAGE_KEY = "kodely:pending_prompt_image";
7	
8	function deriveName(prompt: string): string {
9	  const trimmed = prompt.trim().replace(/\s+/g, " ");
10	  return trimmed.length > 60 ? trimmed.slice(0, 57) + "…" : trimmed || "New site";
11	}
12	
13	/**
14	 * After a successful login/signup, sends the user straight into a new
15	 * project pre-loaded with whatever they typed on the homepage before hitting
16	 * the auth wall, instead of losing it and dropping them on an empty
17	 * dashboard. Returns the path to navigate to — "/dashboard" if there was
18	 * nothing pending or project creation failed for any reason.
19	 */
20	export async function destinationAfterAuth(): Promise<string> {
21	  let prompt: string | null = null;
22	  try {
23	    prompt = sessionStorage.getItem(PENDING_PROMPT_KEY);
24	  } catch {}
25	  if (!prompt) return "/dashboard";
26	
27	  try {
28	    const res = await fetch("/api/projects", {
29	      method: "POST",
30	      headers: { "Content-Type": "application/json" },
31	      body: JSON.stringify({ name: deriveName(prompt) }),
32	    });
33	    const body = await res.json();
34	    if (!res.ok || !body?.project?.id) return "/dashboard";
35	    return `/projects/${body.project.id}`;
36	  } catch {
37	    return "/dashboard";
38	  }
39	}
