1	import { redirect } from "next/navigation";
2	import Link from "next/link";
3	import { getCurrentUser } from "@/lib/auth";
4	import { getBalance, averageBuildCredits, SIGNUP_GRANT } from "@/lib/credits";
5	import { db } from "@/lib/db";
6	import { billingEnabled } from "@/lib/stripe";
7	import CreditMeter from "@/components/CreditMeter";
8	import NewProjectButton from "./NewProjectButton";
9	import ProjectRow from "./ProjectRow";
10	import SignOutButton from "./SignOutButton";
11	import TopUpButton from "./TopUpButton";
12	
13	export const dynamic = "force-dynamic";
14	
15	export default async function DashboardPage() {
16	  const user = await getCurrentUser();
17	  if (!user) redirect("/login");
18	
19	  const [balance, avgBuildCredits, projects] = await Promise.all([
20	    getBalance(user.id),
21	    averageBuildCredits(user.id),
22	    db.project.findMany({
23	      where: { userId: user.id },
24	      orderBy: { updatedAt: "desc" },
25	      select: { id: true, name: true, slug: true, publishedAt: true, updatedAt: true },
26	    }),
27	  ]);
28	
29	  return (
30	    <div className="mx-auto max-w-4xl px-6 py-10">
31	      <div className="mb-8 flex items-center justify-between">
32	        <div>
33	          <div className="text-lg font-semibold tracking-tight">kodely</div>
34	          <p className="text-sm text-black/60 dark:text-white/60">{user.email}</p>
35	        </div>
36	        <div className="flex items-center gap-4">
37	          <CreditMeter
38	            balance={balance}
39	            avgBuildCredits={avgBuildCredits}
40	            reference={SIGNUP_GRANT}
41	            canTopUp={billingEnabled()}
42	          />
43	          {billingEnabled() && <TopUpButton />}
44	          {/* Deliberately NOT gated on billingEnabled(): this page is mostly
45	              the credit statement, which matters just as much — arguably more —
46	              when top-ups are unavailable and someone is trying to work out
47	              where their credits went. */}
48	          <Link
49	            href="/dashboard/billing"
50	            className="text-sm text-black/60 hover:text-black dark:text-white/60 dark:hover:text-white"
51	          >
52	            Billing
53	          </Link>
54	          <Link
55	            href="/settings"
56	            className="text-sm text-black/60 hover:text-black dark:text-white/60 dark:hover:text-white"
57	          >
58	            Settings
59	          </Link>
60	          <SignOutButton />
61	        </div>
62	      </div>
63	
64	      <div className="mb-6 flex items-center justify-between">
65	        <h1 className="text-base font-medium">Your sites</h1>
66	        <NewProjectButton />
67	      </div>
68	
69	      {projects.length === 0 ? (
