"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import { Check, X } from "lucide-react";

// ── First-run panel (presentation + dismissal) ─────────────────────────────
//
// The three rows here are the activation funnel from lib/events.ts, minus the
// signup step you already completed to be looking at this: project.created →
// build.succeeded → project.published. The North Star is the LAST one, so the
// checklist deliberately keeps going after the first successful build rather
// than congratulating someone for stopping halfway.
//
// Progressive, never blocking. This is an inline card above the project list:
// no modal, no tour, no focus trap, nothing between anyone and the raw prompt
// box. Every step is a description of state plus an optional shortcut — none
// of them is a gate.
//
// Visibility is decided in two places for two different reasons:
//   • "are they past this?" is DERIVED, by the server component that renders
//     this (FirstRunChecklist) — a published project makes the panel vanish
//     permanently, because that fact lives in the database already.
//   • "I don't want to see this" is a local UI preference and lives in
//     localStorage. It is not a fact about the account, it can't earn a
//     schema field, and losing it on another device is harmless.

const DISMISS_KEY = "kodely:first-run-dismissed";

const FOCUS_RING =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-black/40 dark:focus-visible:ring-white/40";

export type FirstRunPanelProps = {
  /** They have at least one project (the signup seed counts — it is a real project). */
  hasProject: boolean;
  /** At least one build has SUCCEEDED across all their projects. */
  hasBuild: boolean;
  /** Most recently touched project, for the "open it" shortcut. */
  openProject: { id: string; name: string } | null;
  /** SIGNUP_GRANT, passed in rather than hardcoded so it can never drift. */
  grant: number;
  /** Derived from MICROS_PER_CREDIT — how many credits make one dollar. */
  creditsPerDollar: number;
  /** Size of the starter-prompt gallery at /templates. */
  templateCount: number;
};

type Step = {
  id: string;
  title: string;
  done: boolean;
  /** Shown only while the step is outstanding. */
  body: React.ReactNode;
};

export default function FirstRunPanel({
  hasProject,
  hasBuild,
  openProject,
  grant,
  creditsPerDollar,
  templateCount,
}: FirstRunPanelProps) {
  // "pending" until the effect has read localStorage. Rendering the panel
  // first and hiding it a frame later would flash a card at everyone who
  // already dismissed it, which is the exact nagging this is meant to avoid.
  const [visibility, setVisibility] = useState<"pending" | "visible" | "hidden">("pending");
  const [creditsOpen, setCreditsOpen] = useState(false);

  useEffect(() => {
    let dismissed = false;
    try {
      dismissed = localStorage.getItem(DISMISS_KEY) === "1";
    } catch {
      // Private mode / storage disabled: show it. A panel with a working
      // dismiss button that doesn't persist beats no panel at all.
    }
    setVisibility(dismissed ? "hidden" : "visible");
  }, []);

  function dismiss() {
    try {
      localStorage.setItem(DISMISS_KEY, "1");
    } catch {}
    setVisibility("hidden");
  }

  if (visibility !== "visible") return null;

  const steps: Step[] = [
    {
      id: "create",
      title: "Create a site",
      done: hasProject,
      body: <>Use “New site” above. Every site is a real React app from the first second.</>,
    },
    {
      id: "build",
      title: "Describe it, and build it",
      done: hasBuild,
      body: (
        <>
          Open a site and type what you want in the box at the bottom — plain English, as
          specific as you can manage.{" "}
          <Link href="/templates" className={`underline underline-offset-2 hover:no-underline ${FOCUS_RING} rounded`}>
            Not sure what to type? Start from one of {templateCount} written prompts
          </Link>
          . If you have already typed something rough, press <strong className="font-medium">Enhance</strong>{" "}
          next to the box: it expands your line into a fuller spec you can read and edit
          first, and it costs no credits.
        </>
      ),
    },
    {
      id: "publish",
      title: "Publish it",
      done: false,
      body: (
        <>
          When it looks right, hit Publish on the site’s page. That is the point it gets a
          real address you can send to someone.
        </>
      ),
    },
  ];

  const doneCount = steps.filter((s) => s.done).length;

  return (
    <section
      aria-labelledby="first-run-heading"
      className="mb-6 rounded-xl border border-black/10 p-4 text-sm dark:border-white/10"
    >
      <div className="flex items-start justify-between gap-3">
        <div className="min-w-0">
          <h2 id="first-run-heading" className="text-sm font-medium">
            Getting started
          </h2>
          <p className="mt-0.5 text-xs text-black/50 dark:text-white/50">
            {doneCount} of {steps.length} done · your first published site is the finish line
          </p>
        </div>
        <button
          type="button"
          onClick={dismiss}
          aria-label="Dismiss getting started"
          className={`-m-1 shrink-0 rounded-lg p-1 text-black/40 hover:text-black dark:text-white/40 dark:hover:text-white ${FOCUS_RING}`}
        >
          <X size={16} aria-hidden />
        </button>
      </div>

      <ol className="mt-3 space-y-2.5">
        {steps.map((step) => (
          <li key={step.id} className="flex gap-2.5">
            <span
              aria-hidden
              className={
                step.done
                  ? "mt-0.5 flex h-4 w-4 shrink-0 items-center justify-center rounded-full bg-black text-white dark:bg-white dark:text-black"
                  : "mt-0.5 h-4 w-4 shrink-0 rounded-full border border-black/25 dark:border-white/25"
              }
            >
              {step.done && <Check size={11} strokeWidth={3} />}
            </span>
            <div className="min-w-0">
              <p className={step.done ? "text-black/45 dark:text-white/45" : "font-medium"}>
                {step.title}
                {step.done && <span className="sr-only"> — done</span>}
              </p>
              {!step.done && (
                <p className="mt-1 text-black/60 dark:text-white/60">{step.body}</p>
              )}
            </div>
          </li>
        ))}
      </ol>

      {/* The shortcut only exists once there is something to open, and only
          while building is still the outstanding step — after that it would
          just be a second, worse copy of the project list below. */}
      {hasProject && !hasBuild && openProject && (
        <Link
          href={`/projects/${openProject.id}`}
          className={`mt-3 inline-flex max-w-full items-center gap-1.5 rounded-lg bg-black px-3 py-1.5 text-sm font-medium text-white dark:bg-white dark:text-black ${FOCUS_RING}`}
        >
          <span className="truncate">Open {openProject.name}</span>
          <span aria-hidden>→</span>
        </Link>
      )}

      <div className="mt-4 border-t border-black/10 pt-3 dark:border-white/10">
        <button
          type="button"
          onClick={() => setCreditsOpen((v) => !v)}
          aria-expanded={creditsOpen}
          aria-controls="first-run-credits"
          className={`rounded text-xs text-black/60 underline underline-offset-2 hover:text-black hover:no-underline dark:text-white/60 dark:hover:text-white ${FOCUS_RING}`}
        >
          {creditsOpen ? "Hide" : "What is a credit?"}
        </button>

        {/* Kept mounted so aria-controls always points at a real element. */}
        <div id="first-run-credits" hidden={!creditsOpen}>
          <CreditPrimer grant={grant} creditsPerDollar={creditsPerDollar} />
        </div>
      </div>
    </section>
  );
}

// ── The credits explanation ────────────────────────────────────────────────
//
// Everything here is a fact taken from lib/credits.ts, and one thing is
// deliberately absent: a price per build. Our two real measurements are 144
// and 472 credits — a 3x spread — and estimateCredits' own comment says two
// data points are not a distribution. Quoting an average would be inventing
// precision we do not have, on the one topic (bill shock) where this product
// claims to be more honest than the category. So the answer to "what will
// this cost me?" points at the meter, which is computed from that person's
// own build history, rather than at a number made up here.
function CreditPrimer({ grant, creditsPerDollar }: { grant: number; creditsPerDollar: number }) {
  return (
    <dl className="mt-2.5 space-y-2.5 text-xs leading-relaxed text-black/60 dark:text-white/60">
      <div>
        <dt className="font-medium text-black/80 dark:text-white/80">A credit is real spend</dt>
        <dd>
          One credit is a fixed amount of actual model spend — {creditsPerDollar} credits is $1.
          It is not a made-up point system, and it is not per-message.
        </dd>
      </div>
      <div>
        <dt className="font-medium text-black/80 dark:text-white/80">
          You start with {grant}
        </dt>
        <dd>
          Enough to get a first site built and iterate on it. How far it goes after that
          depends on how much you ask for — a bigger site costs more than a small one, so we
          do not quote a flat price per build. The meter at the top of this page estimates
          how many builds you have left from your own history.
        </dd>
      </div>
      <div>
        <dt className="font-medium text-black/80 dark:text-white/80">Failed builds are free</dt>
        <dd>
          You are charged only for a build that succeeds. A build that breaks, or one you
          stop halfway, costs you nothing.
        </dd>
      </div>
      <div>
        <dt className="font-medium text-black/80 dark:text-white/80">You can cap your spend</dt>
        <dd>
          Set a ceiling for a rolling 30 days in{" "}
          <Link
            href="/settings"
            className={`underline underline-offset-2 hover:no-underline ${FOCUS_RING} rounded`}
          >
            Settings
          </Link>{" "}
          and a long session cannot run past it.
        </dd>
      </div>
    </dl>
  );
}

import { getCurrentUser } from "@/lib/auth";
import { db } from "@/lib/db";
import { MICROS_PER_CREDIT, SIGNUP_GRANT } from "@/lib/credits";
import { TEMPLATES } from "@/lib/templates";
import FirstRunPanel from "./FirstRunPanel";

// ── First-run experience (state) ───────────────────────────────────────────
//
// Renders itself. One import and one <FirstRunChecklist /> on the dashboard is
// the whole integration — it fetches its own data so the page it lives on does
// not have to grow props for it.
//
// The steps mirror the activation funnel in lib/events.ts exactly
// (project.created → build.succeeded → project.published), and each one is
// answered from the database rather than from a stored "onboarding step"
// column. Two reasons that matters:
//
//   1. It cannot lie. Someone who published from a second device, or whose
//      first build succeeded in another tab, sees the truth on next load. A
//      progress column would drift the first time anything happened outside
//      this component.
//   2. It cannot nag. The panel disappears the moment a project is published
//      — permanently, with no flag to write and none to reset — because
//      "published" is a fact that already exists in the schema. Reaching the
//      North Star is the exit condition.
//
// Anyone who wants it gone sooner uses the dismiss button, which is a
// localStorage preference owned by FirstRunPanel (see the note there).

export default async function FirstRunChecklist() {
  const user = await getCurrentUser();
  // The dashboard already redirects signed-out visitors; this is just so the
  // component is safe to drop anywhere without assuming that.
  if (!user) return null;

  const [publishedCount, hasProjectCount, succeededBuilds, openProject] = await Promise.all([
    db.project.count({ where: { userId: user.id, publishedAt: { not: null } } }),
    db.project.count({ where: { userId: user.id } }),
    db.build.count({ where: { project: { userId: user.id }, status: "SUCCEEDED" } }),
    db.project.findFirst({
      where: { userId: user.id },
      orderBy: { updatedAt: "desc" },
      select: { id: true, name: true },
    }),
  ]);

  // Past the funnel. Nothing further to guide them through, so this never
  // renders again for this account.
  if (publishedCount > 0) return null;

  return (
    <FirstRunPanel
      hasProject={hasProjectCount > 0}
      hasBuild={succeededBuilds > 0}
      openProject={openProject}
      grant={SIGNUP_GRANT}
      // 1e6 micro-dollars = $1, so this is credits-per-dollar without a second
      // constant that could disagree with lib/credits.ts.
      creditsPerDollar={Math.round(1_000_000 / MICROS_PER_CREDIT)}
      templateCount={TEMPLATES.length}
    />
  );
}

