3	import { useState, useSyncExternalStore, type ReactNode } from "react";
4	import Link from "next/link";
5	import { Check, X } from "lucide-react";
6	
7	// ── First-run panel (presentation + dismissal) ─────────────────────────────
8	//
9	// The three rows here are the activation funnel from lib/events.ts, minus the
10	// signup step you already completed to be looking at this: project.created →
11	// build.succeeded → project.published. The North Star is the LAST one, so the
12	// checklist deliberately keeps going after the first successful build rather
13	// than congratulating someone for stopping halfway.
14	//
15	// Progressive, never blocking. This is an inline card above the project list:
16	// no modal, no tour, no focus trap, nothing between anyone and the raw prompt
17	// box. Every step is a description of state plus an optional shortcut — none
18	// of them is a gate.
19	//
20	// Visibility is decided in two places for two different reasons:
21	//   • "are they past this?" is DERIVED, by the server component that renders
22	//     this (FirstRunChecklist) — a published project makes the panel vanish
23	//     permanently, because that fact lives in the database already.
24	//   • "I don't want to see this" is a local UI preference and lives in
25	//     localStorage. It is not a fact about the account, it can't earn a
26	//     schema field, and losing it on another device is harmless.
27	
28	const DISMISS_KEY = "kodely:first-run-dismissed";
29	
30	const FOCUS_RING =
31	  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-black/40 dark:focus-visible:ring-white/40";
32	
33	// localStorage read as an external store, rather than state synced in an
34	// effect. Two things fall out of it for free: the server snapshot is "already
35	// dismissed", so nothing is ever server-rendered and then yanked away a frame
36	// later; and dismissing in one tab hides it in the others.
37	const dismissListeners = new Set<() => void>();
38	
39	function subscribeDismissed(onChange: () => void) {
40	  dismissListeners.add(onChange);
41	  window.addEventListener("storage", onChange);
42	  return () => {
43	    dismissListeners.delete(onChange);
44	    window.removeEventListener("storage", onChange);
45	  };
46	}
47	
48	/**
49	 * Set when the button is pressed, so dismissing still works on this page view
50	 * even where localStorage is unavailable (private mode, storage disabled, a
51	 * full quota). There it simply doesn't survive a reload, which is a far better
52	 * failure than a card that cannot be closed.
53	 */
54	let dismissedThisSession = false;
55	
56	function readDismissed(): boolean {
57	  if (dismissedThisSession) return true;
58	  try {
59	    return localStorage.getItem(DISMISS_KEY) === "1";
60	  } catch {
61	    return false;
62	  }
63	}
64	
65	/** Server/hydration snapshot: hidden until the real answer is known. */
66	function readDismissedOnServer(): boolean {
67	  return true;
68	}
69	
70	function writeDismissed() {
71	  dismissedThisSession = true;
72	  try {
73	    localStorage.setItem(DISMISS_KEY, "1");
74	  } catch {}
75	  for (const onChange of dismissListeners) onChange();
76	}
77	
78	export type FirstRunPanelProps = {
79	  /** They have at least one project (the signup seed counts — it is a real project). */
80	  hasProject: boolean;
81	  /** At least one build has SUCCEEDED across all their projects. */
82	  hasBuild: boolean;
83	  /** Most recently touched project, for the "open it" shortcut. */
84	  openProject: { id: string; name: string } | null;

